#!/usr/bin/env python3
"""docs/licenses.md from Buildroot's legal-info manifest (out/<variant>/manifest.csv)."""
import csv
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
rows = []
for variant in ("prod", "dev"):
    p = os.path.join(ROOT, "out", variant, "manifest.csv")
    if os.path.exists(p):
        with open(p) as f:
            for r in csv.DictReader(f):
                rows.append((variant, r))

prod = {r["PACKAGE"] for v, r in rows if v == "prod"}
out = ["# EdgeSight licence list", "",
       "Generated by `scripts/gen-licenses.py` from Buildroot `make legal-info` "
       "(`out/prod/manifest.csv`, `out/dev/manifest.csv`). Full licence texts: "
       "`$EDGESIGHT_WORK/output-<variant>/legal-info/licenses/`.", "",
       "**Proprietary components: none.** ONNX Runtime is MIT-licensed open source, installed from "
       "Microsoft's official binary release (see `ThirdPartyNotices.txt` in legal-info).", "",
       "| Package | Version | Licence | Licence files | Image |", "|---|---|---|---|---|"]
seen = set()
for v, r in rows:
    name = r["PACKAGE"]
    if name in seen:
        continue
    seen.add(name)
    img = "prod + dev" if name in prod and v == "prod" else "dev only"
    ver = r["VERSION"] if len(r["VERSION"]) < 20 else r["VERSION"][:12] + "…"
    lic = r["LICENSE"]
    if name == "toolchain-external-bootlin" and lic in ("unknown", ""):
        # Buildroot cannot introspect a prebuilt toolchain; what lands on the target is its runtime:
        lic = "glibc: LGPL-2.1+; libstdc++/libgcc: GPL-3.0+ with GCC Runtime Library Exception"
    out.append(f"| {name} | {ver} | {lic} | {r.get('LICENSE FILES', '').replace(' ', ', ')} | {img} |")
open(os.path.join(ROOT, "docs", "licenses.md"), "w").write("\n".join(out) + "\n")
print(f"{len(seen)} packages written to docs/licenses.md")
